
-- BuyerLens: Customer Shopping Behavior Analytics
-- SQL is written for MySQL 8.0+ and expects the cleaned `customer` table
-- created from the notebook. These queries were reviewed, not run against
-- a MySQL server in this workspace.

-- Q1. What is the total revenue generated by male vs. female customers?
SELECT gender, SUM(purchase_amount) AS revenue
FROM customer
GROUP BY gender;

-- Q2. Which customers used a discount but still spent more than the average?
SELECT customer_id, purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
  AND purchase_amount > (SELECT AVG(purchase_amount) FROM customer);

-- Q3. Which are the top 5 products with the highest average review rating?
SELECT item_purchased,
       ROUND(AVG(review_rating), 2) AS average_product_rating
FROM customer
GROUP BY item_purchased
ORDER BY average_product_rating DESC
LIMIT 5;

-- Q4. Compare average purchase amounts for Standard and Express Shipping.
SELECT shipping_type,
       ROUND(AVG(purchase_amount), 2) AS average_purchase_amount
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;

-- Q5. Compare average spend and total revenue for subscribers and non-subscribers.
SELECT subscription_status,
       COUNT(customer_id) AS total_records,
       ROUND(AVG(purchase_amount), 2) AS average_spend,
       ROUND(SUM(purchase_amount), 2) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC, average_spend DESC;

-- Q6. Which 5 products have the highest percentage of purchases with discounts?
SELECT item_purchased,
       ROUND(
           100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)
           / COUNT(*),
           2
       ) AS discount_rate_percent
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate_percent DESC
LIMIT 5;

-- Q7. Segment records by previous purchase count.
-- In this dataset, "New" means 1 previous purchase, not zero prior purchases.
WITH customer_type AS (
    SELECT customer_id,
           previous_purchases,
           CASE
               WHEN previous_purchases = 1 THEN 'New'
               WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
               ELSE 'Loyal'
           END AS customer_segment
    FROM customer
)
SELECT customer_segment, COUNT(*) AS number_of_records
FROM customer_type
GROUP BY customer_segment;

-- Q8. What are the top 3 most purchased products within each category?
WITH item_counts AS (
    SELECT category,
           item_purchased,
           COUNT(customer_id) AS total_orders,
           ROW_NUMBER() OVER (
               PARTITION BY category
               ORDER BY COUNT(customer_id) DESC
           ) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT item_rank, category, item_purchased, total_orders
FROM item_counts
WHERE item_rank <= 3;

-- Q9. Compare the repeat-buyer share within each subscription group.
SELECT subscription_status,
       COUNT(customer_id) AS total_records,
       SUM(CASE WHEN previous_purchases > 5 THEN 1 ELSE 0 END) AS repeat_buyers,
       ROUND(
           100.0 * SUM(CASE WHEN previous_purchases > 5 THEN 1 ELSE 0 END)
           / COUNT(customer_id),
           2
       ) AS repeat_buyer_percent
FROM customer
GROUP BY subscription_status;

-- Q10. What is the revenue contribution of each age group?
SELECT age_group,
       SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;
